+		if b.Len() != 0 {
+			t.Errorf("hook %q wrote a notice: %q", hook, b.String())
+		}
+	}
+
+	// An empty notice (silent reason) writes nothing even on session-start.
+	var b bytes.Buffer
+	warnInactiveOnSessionStart(&b, "session-start", "")
+	if b.Len() != 0 {
+		t.Errorf("empty notice wrote output: %q", b.String())
+	}
+}
