528:// checkGlobalTracking runs the global-mode diagnostics. Warn-only:
529://
530://  1. Global tracking is on but user-level agent hooks are missing for an
531://     agent that supports them — sessions in never-enabled repos cannot fire
532://     a hook for those agents. Fix: `entire enable --global` (idempotent)
533://     re-installs them.
534://  2. This clone carries the globally_enabled clone-preferences marker but
535://     its git hooks are gone. Informational: the lazy setup path self-heals
536://     on the next agent session in this clone.
537://
538:// Both checks stay silent while the global tier is unconfigured or off.
539:func checkGlobalTracking(cmd *cobra.Command) {
540:	ctx := cmd.Context()
541:	us, err := settings.LoadUserSettings(ctx)
542:	if err != nil || us.Global == nil || !us.Global.Enabled {
543:		return
544:	}
545:	w := cmd.OutOrStdout()
546:
547:	var missing []string
548:	for _, name := range agent.List() {
549:		ag, agErr := agent.Get(name)
550:		if agErr != nil {
551:			continue
552:		}
553:		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
554:			continue
555:		}
556:		uhs, ok := agent.AsUserHookSupport(ag)
557:		if !ok {
558:			continue
559:		}
560:		if !uhs.AreUserHooksInstalled(ctx) {
561:			missing = append(missing, string(name))
562:		}
563:	}
564:	if len(missing) == 0 {
565:		fmt.Fprintln(w, "✓ Global tracking: user-level agent hooks OK")
566:	} else {
567:		fmt.Fprintln(w, "Global tracking: USER-LEVEL AGENT HOOKS MISSING")
568:		fmt.Fprintf(w, "  Global tracking is on, but user-level hooks are not installed for: %s\n", strings.Join(missing, ", "))
569:		fmt.Fprintln(w, "  Sessions in repos without repo-level setup are not tracked for those agents.")
570:		fmt.Fprintln(w, "  Run `entire enable --global` to install them.")
571:	}
572:
573:	// Clone-local check: only meaningful when the lazy setup already ran here.
574:	prefs, prefsErr := settings.LoadClonePreferences(ctx)
575:	if prefsErr != nil || !prefs.GloballyEnabled {
576:		return
577:	}
578:	if !strategy.IsGitHookInstalled(ctx) {
579:		fmt.Fprintln(w, "Globally tracked clone: GIT HOOKS MISSING")
580:		fmt.Fprintln(w, "  This clone was enabled by global tracking but its git hooks are gone.")
581:		fmt.Fprintln(w, "  No action needed: the next agent session here reinstalls them (the lazy setup self-heals).")
582:	}
583:}
